def average_Odd(n) :
    if (n%2==0) :
        return ("Invalid Input")
        return -1
    sm =0
    count =0
    while (n>=1) :
        count=count+1
        sm = sm + n
        n = n-2
    return sm//count

def no_of_subsequences(arr, k):
    n = len(arr)
    dp = [[0 for i in range(n + 1)]
            for j in range(k + 1)]
    for i in range(1, k + 1):
        for j in range(1, n + 1):
            dp[i][j] = dp[i][j - 1]
            if arr[j - 1] <= i and arr[j - 1] > 0:
                dp[i][j] += dp[i // arr[j - 1]][j - 1] + 1
    return dp[k][n]

